SELECT CASE WHEN duration_sec >= 361 THEN 'high' WHEN duration_sec >= 146 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, CASE WHEN page IN ('/cart', '/checkout') THEN 'tier_1' ELSE 'other' END AS page_group, ROUND(AVG(duration_sec), 2) AS avg_duration_sec FROM web_events GROUP BY CASE WHEN duration_sec >= 361 THEN 'high' WHEN duration_sec >= 146 THEN 'mid' ELSE 'low' END, CASE WHEN page IN ('/cart', '/checkout') THEN 'tier_1' ELSE 'other' END ORDER BY avg_duration_sec DESC, page_group DESC
